/*
 * lmt_make.c - C23 replacement for lmt_make.pl
 *
 * Creates the C table that lists the modules statically linked into the
 * interpreter (or into any other embedding application). Usage:
 *
 *     lmt_make lmt_none.def [lmt_httpd.def ...]
 *
 * For every input file lmt_XXX.def a lmt_XXX.c is generated. The file is
 * only written when the content actually changed, so the timestamp is
 * preserved and make does not relink needlessly.
 *
 * Faithful port: the generated files are byte identical to the Perl ones.
 */
#define _POSIX_C_SOURCE 200809L

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_MODULES 512

static int is_sp(char c)
{
    return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f' || c == '\v';
}

static char *read_file(const char *name, size_t *size)
{
    FILE *f = fopen(name, "rb");
    if (!f) return NULL;
    size_t cap = 4096, len = 0;
    char *buf = malloc(cap);
    size_t n;
    while ((n = fread(buf + len, 1, cap - len, f)) > 0) {
        len += n;
        if (len == cap) { cap *= 2; buf = realloc(buf, cap); }
    }
    fclose(f);
    buf = realloc(buf, len + 1);
    buf[len] = 0;
    if (size) *size = len;
    return buf;
}

int main(int argc, char **argv)
{
    for (int ai = 1; ai < argc; ai++) {
        const char *input = argv[ai];
        char *modules[MAX_MODULES];
        int   n_modules = 0;

        FILE *f = fopen(input, "r");
        if (!f) { printf("Cannot open %s\n", input); return 1; }

        char  *line = NULL;
        size_t capacity = 0;
        ssize_t len;
        while ((len = getline(&line, &capacity, f)) > 0) {
            while (len > 0 && line[len - 1] == '\n') line[--len] = 0; /* chomp */
            char *s = line;
            while (is_sp(*s)) s++;
            if (*s == 0 || *s == '#') continue;
            /* first whitespace separated word */
            char *end = s;
            while (*end && !is_sp(*end)) end++;
            char save = *end;
            *end = 0;
            if (n_modules < MAX_MODULES) modules[n_modules++] = strdup(s);
            *end = save;
        }
        fclose(f);

        /* build the output text */
        size_t cap = 1024, out_len = 0;
        char *outbuf = malloc(cap);
        #define OUTF(...) do { \
            int needed = snprintf(NULL, 0, __VA_ARGS__); \
            if (out_len + (size_t)needed + 1 > cap) { \
                while (out_len + (size_t)needed + 1 > cap) cap *= 2; \
                outbuf = realloc(outbuf, cap); \
            } \
            out_len += (size_t)snprintf(outbuf + out_len, cap - out_len, __VA_ARGS__); \
        } while (0)
        #define OUTF_FIX(str) do { \
            size_t needed = strlen(str); \
            if (out_len + needed + 1 > cap) { \
                while (out_len + needed + 1 > cap) cap *= 2; \
                outbuf = realloc(outbuf, cap); \
            } \
            memcpy(outbuf + out_len, str, needed + 1); \
            out_len += needed; \
        } while (0)

        OUTF("/* FILE: %s\n\n", input);
        OUTF_FIX("This file was automatically created by the program lmt_make\n\n");
        OUTF_FIX("DO NOT EDIT THIS FILE!!!\n\n");
        OUTF("Rather edit the file %s that is the source \n\n", input);
        OUTF_FIX("*/\n#include <stdio.h>\n#include \"basext.h\"\n\n");

        for (int i = 0; i < n_modules; i++) {
            char upper[256];
            size_t j;
            for (j = 0; modules[i][j] && j < sizeof upper - 1; j++) {
                char c = modules[i][j];
                upper[j] = (c >= 'a' && c <= 'z') ? (char)(c - 'a' + 'A') : c;
            }
            upper[j] = 0;
            OUTF("extern SLFST %s_SLFST[];\n", upper);
        }

        OUTF_FIX("MODLIST StaticallyLinkedModules[] ={\n");
        for (int i = 0; i < n_modules; i++) {
            char upper[256];
            size_t j;
            for (j = 0; modules[i][j] && j < sizeof upper - 1; j++) {
                char c = modules[i][j];
                upper[j] = (c >= 'a' && c <= 'z') ? (char)(c - 'a' + 'A') : c;
            }
            upper[j] = 0;
            OUTF("  {\"%s\" , (void *)%s_SLFST },\n", modules[i], upper);
        }
        OUTF_FIX("  { NULL, NULL },\n");
        OUTF_FIX("  };\n");

        /* the name of the output: a trailing "def" is replaced by "c", and the
           C source files of the interpreter live in src/ */
        char *base = strdup(input);
        size_t l = strlen(base);
        if (l >= 3 && strcmp(base + l - 3, "def") == 0) {
            base[l - 3] = 'c';
            base[l - 2] = 0;
        }
        char *output = malloc(strlen(base) + 5);
        sprintf(output, "src/%s", base);
        free(base);

        /* write only when the content changed */
        size_t old_len = 0;
        char *old = read_file(output, &old_len);
        int identical = old && old_len == out_len && memcmp(old, outbuf, out_len) == 0;
        free(old);
        if (!identical) {
            FILE *o = fopen(output, "w");
            if (!o) { fprintf(stderr, "Cannot open output file %s\n", output); return 1; }
            fwrite(outbuf, 1, out_len, o);
            fclose(o);
        }
        free(output);
        free(outbuf);
        for (int i = 0; i < n_modules; i++) free(modules[i]);
    }
    return 0;
}
